#!/usr/bin/env node
// Writes src/_version.scss from package.json `version`, the single source of
// truth for the theme's version. Run before build, watch and size (npm pre-hooks);
// the generated file is git-ignored, so never edit it or write a version by hand in src/.
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const { version } = require(path.join(root, "package.json"));
fs.writeFileSync(
  path.join(root, "src", "_version.scss"),
  `// Generated by scripts/write-version.js from package.json. Do not edit.\n$version: "${version}";\n`
);
